/** Full Utility sheets through both actual native Door orchestration paths, with fallback/reload controls. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeUtilityDoorChecks {
 private static NativeDoorRenderer.Bake bake;private static NativeProgrammableDoorEntity.Visual[] scenes;private static int frames,phase,checks,titleTicks;private static int[] baseline,positive;private static java.util.concurrent.CompletableFuture<Void> reload;private static boolean capture;
 private static final class Gallery extends net.minecraft.client.gui.screens.Screen {Gallery(){super(net.minecraft.network.chat.Component.empty());}@Override public void render(net.minecraft.client.gui.GuiGraphics graphics,int x,int y,float partial){}}
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_UTILITY_DOOR_RENDER_CHECK"));}
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Utility native Door "+phase+": "+why);}
 private static void prepare(){var mc=Minecraft.getInstance();var wall=NativePanelPlaybackRenderer.currentBake();need(wall!=null,"coherent material bake");bake=new NativeDoorRenderer.Bake(id->mc.getModelManager().getModel(ModelResourceLocation.standalone(ResourceLocation.parse(id))),material->mc.getTextureAtlas(material.atlasLocation()).apply(material.texture()),wall);var choices=new ArrayList<Integer>();for(int i=0;i<ModernFinishCatalog.ENTRIES.size();i++)if(ModernFinishCatalog.option(i).id().startsWith("utility_door_"))choices.add(i);need(choices.size()==12,"all supplied sheets");scenes=new NativeProgrammableDoorEntity.Visual[24];
  for(int i=0;i<24;i++){boolean large=i>=12;int choice=choices.get(i%12);var descriptor=NativeDoorAssets.preview(choice);var sprite=mc.getTextureAtlas(TextureAtlas.LOCATION_BLOCKS).apply(ResourceLocation.parse(descriptor.texture()));need(sprite.contents() instanceof NativeDoorSpriteSource.Contents content&&content.usedU()==.5F&&content.usedV()==1,"actual full1:2 padded sprite "+descriptor.id());var base=NativeDoorSettings.fresh(large,true);var settings=new NativeDoorSettings(new SpaceDoorData(2,1,true,0,false,true,true,0,false),phase==0?-1:choice,0,false,1,1,0,127,base.frames(),NativeDoorGlass.DEFAULT);var state=NativeDoorRegistrations.ORDINARY.get().defaultBlockState().setValue(NativeProgrammableDoorBlock.FACING,Direction.SOUTH).setValue(NativeProgrammableDoorBlock.HINGE,DoorHingeSide.RIGHT).setValue(NativeProgrammableDoorBlock.PAIRED,large);scenes[i]=new NativeProgrammableDoorEntity.Visual(settings,state,SpaceDoorControlPanel.Side.NONE,large,false);}
 }
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(enabled()&&Minecraft.getInstance().screen instanceof net.minecraft.client.gui.screens.TitleScreen&&Minecraft.getInstance().getOverlay()==null)if(++titleTicks==80)Minecraft.getInstance().setScreen(new Gallery());}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||titleTicks<80||phase==3||!(event.getScreen() instanceof Gallery))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null||reload!=null&&!reload.isDone())return;if(reload!=null){reload.join();reload=null;prepare();}if(bake==null)prepare();var graphics=event.getGuiGraphics();com.mojang.blaze3d.systems.RenderSystem.setShaderColor(1,1,1,1);graphics.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);graphics.flush();var buffers=mc.renderBuffers().bufferSource();for(int i=0;i<24;i++){int x=10+i%6*210,y=10+i/6*175;graphics.enableScissor(x,y,x+200,y+165);var poses=graphics.pose();poses.pushPose();try{poses.translate(x+45,y+155,300);float scale=i>=12?42:65;poses.scale(scale,-scale,scale);if(i>=12)NativeDoorRenderer.renderLargeAt(bake,scenes[i],mc,new BlockPos(i,0,0),0,0,poses,buffers,0xf000f0,OverlayTexture.NO_OVERLAY);else NativeDoorRenderer.renderAt(bake,scenes[i],mc,new BlockPos(i,0,0),0,0,poses,buffers,0xf000f0,OverlayTexture.NO_OVERLAY);}finally{poses.popPose();}buffers.endBatch();graphics.flush();graphics.disableScissor();}capture=++frames>=10;}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(!enabled()||!capture)return;capture=false;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){int w=image.getWidth(),h=image.getHeight();var pixels=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)pixels[y*w+x]=image.getPixelRGBA(x,y);if(phase==0){baseline=pixels;phase=1;frames=0;prepare();return;}if(phase==1){positive=pixels;double s=mc.getWindow().getGuiScale();for(int i=0;i<24;i++){int changed=0;for(int y=(int)((10+i/6*175)*s);y<(10+i/6*175+165)*s;y++)for(int x=(int)((10+i%6*210)*s);x<(10+i%6*210+200)*s;x++)if(pixels[y*w+x]!=baseline[y*w+x])changed++;need(changed>300,"actual selected material vs default scene="+i+" changed="+changed);}var file=mc.gameDirectory.toPath().resolve("screenshots/utility-doors.png");java.nio.file.Files.createDirectories(file.getParent());image.writeToFile(file);phase=2;frames=0;bake=null;reload=mc.reloadResourcePacks();return;}var reloaded=mc.gameDirectory.toPath().resolve("screenshots/utility-doors-reloaded.png");image.writeToFile(reloaded);int mismatches=0,x0=w,y0=h,x1=0,y1=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(positive[y*w+x]!=pixels[y*w+x]){mismatches++;x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}need(Arrays.equals(positive,pixels),"identical actual artwork after resource reload mismatches="+mismatches+" bounds="+x0+","+y0+".."+x1+","+y1);phase=3;System.out.println("[vandorlabs][utility-door-native] title PASS scenes24 supplied12/ordinaryLarge actualfull1:2sprites/defaultmaterialnegative/identicalreload checks="+checks);mc.stop();}}
}
